```java
// required=false → null if missing
@GetMapping("/users")
public List<User> getUsers(
    @RequestParam(required = false) String nameFilter
) {
    if (nameFilter == null) return userService.findAll();
    return userService.findByName(nameFilter);
}

// defaultValue → use fallback if missing
@GetMapping("/users")
public Page<User> getUsers(
    @RequestParam(defaultValue = "0") int page,
    @RequestParam(defaultValue = "20") int size,
    @RequestParam(defaultValue = "id") String sortBy
) {
    return userService.findAll(PageRequest.of(page, size, Sort.by(sortBy)));
}
```

